script:
% Preserve mission-name source Δ
Create Variable Keep I Count U Quantity Cost;
Keep = 41;
I = 0;
Count = 0;
U = 1;
Quantity = 0;
Cost = 0;
Create Spacecraft Sat;
Sat.DateFormat = A1ModJulian;
Sat.Epoch = 21545;
Sat.CoordinateSystem = EarthMJ2000Eq;
Sat.DisplayStateType = Cartesian;
Sat.X = 7000;
Sat.Y = 0;
Sat.Z = 0;
Sat.VX = 0;
Sat.VY = @SPEED@;
Sat.VZ = 0;
Create ForceModel FM;
FM.PrimaryBodies = {};
FM.PointMasses = {Earth};
FM.SRP = Off;
FM.Drag = None;
Create Propagator P;
P.FM = FM;
P.Type = RungeKutta89;
P.InitialStepSize = 10;
P.MinStep = 10;
P.MaxStep = 10;
P.Accuracy = 1e-12;
Create XYPlot Trace Control;
Trace.XVariable = Sat.ElapsedSecs;
Trace.YVariables = {Sat.ElapsedSecs};
Control.XVariable = Sat.ElapsedSecs;
Control.YVariables = {Sat.ElapsedSecs};
Create ReportFile Values Extra;
Values.Filename = '@VALUES@';
Extra.Filename = '@EXTRA@';
Values.WriteHeaders = false;
Values.FixedWidth = false;
Values.Delimiter = ',';
Values.Precision = 17;
Extra.WriteHeaders = false;
Extra.FixedWidth = false;
Extra.Precision = 17;
%
%   Ex_FilterSmoother_GpsPosVec
%
%   Run the Extended Kalman Filter and Fraser-Potter smoother in cold-start mode. 
%   Estimate a first-order Gauss-Markov coefficient of drag correction.
%
%   Released: R2022a
%


%----------------------------------------
%---------- Spacecraft
%----------------------------------------

Create Spacecraft SimSat;

SimSat.DateFormat        = UTCGregorian;
SimSat.Epoch             = '10 Jun 2010 00:00:00.000';
SimSat.CoordinateSystem  = EarthMJ2000Eq;
SimSat.DisplayStateType  = Cartesian;
SimSat.X = 7000;
SimSat.Y = 0;
SimSat.Z = 0;
SimSat.VX = 0;
SimSat.VY = 7.5460532872678359;
SimSat.VZ = 0;
SimSat.DryMass           = 50;
SimSat.Cd                = 2.2;
SimSat.Cr                = 1.8;
SimSat.DragArea          = 10;
SimSat.SRPArea           = 10;
SimSat.Id                = 'LEOSat';
SimSat.AddHardware       = {GpsReceiver, GpsAntenna};

Create Spacecraft EstSat;

EstSat.DateFormat        = UTCGregorian;
EstSat.Epoch             = '10 Jun 2010 00:00:00.000';
EstSat.CoordinateSystem  = EarthMJ2000Eq;
EstSat.DisplayStateType  = Cartesian;
EstSat.X = 7000;
EstSat.Y = 0;
EstSat.Z = 0;
EstSat.VX = 0;
EstSat.VY = 7.5460532872678359;
EstSat.VZ = 0;
EstSat.DryMass           = 50;
EstSat.Cd                = 2.2;
EstSat.CdSigma           = 0.2;
EstSat.Cr                = 1.8;
EstSat.DragArea          = 10;
EstSat.SRPArea           = 10;
EstSat.Id                = 'LEOSat';
EstSat.AddHardware       = {GpsReceiver, GpsAntenna};
EstSat.SolveFors = {CartesianState};
EstSat.ProcessNoiseModel = SNC;

Create CoordinateSystem EstSatVNB;

EstSatVNB.Origin    = EstSat;
EstSatVNB.Axes      = ObjectReferenced;
EstSatVNB.XAxis     = V;
EstSatVNB.YAxis     = N;
EstSatVNB.Primary   = Earth;
EstSatVNB.Secondary = EstSat;

Create ProcessNoiseModel SNC;

SNC.Type             = StateNoiseCompensation;
SNC.CoordinateSystem = EstSatVNB;
SNC.AccelNoiseSigma  = [1.0e-9 1.0e-8 1.0e-8];
SNC.UpdateTimeStep   = 120;

Create EstimatedParameter FogmCd

FogmCd.Model              = 'FirstOrderGaussMarkov'
FogmCd.SolveFor           = 'Cd';
FogmCd.SteadyStateValue   = 2.0
FogmCd.SteadyStateSigma   = 0.2
FogmCd.HalfLife           = 86400

%----------------------------------------
%---------- Spacecraft hardware
%----------------------------------------

Create Antenna GpsAntenna;
Create Receiver GpsReceiver;

GpsReceiver.PrimaryAntenna = GpsAntenna;
GpsReceiver.Id             = 800;
GpsReceiver.ErrorModels    = {PosVecModel}

Create ErrorModel PosVecModel;

PosVecModel.Type       = 'GPS_PosVec'
PosVecModel.NoiseSigma = 0.010;

%----------------------------------------
%---------- Tracking file sets
%----------------------------------------

Create TrackingFileSet SimData;

SimData.AddTrackingConfig       = {{SimSat.GpsReceiver}, 'GPS_PosVec'};
SimData.FileName                = {'@OBS@'};
SimData.RampTable               = {};
SimData.UseLightTime            = False;
SimData.UseRelativityCorrection = False;
SimData.UseETminusTAI           = True;
SimData.DataFilters             = {};

Create TrackingFileSet EstData;

EstData.AddTrackingConfig       = {{EstSat.GpsReceiver}, 'GPS_PosVec'};
EstData.FileName                = {'@OBS@'};
EstData.RampTable               = {};
EstData.UseLightTime            = False;
EstData.UseRelativityCorrection = False;
EstData.UseETminusTAI           = True;
EstData.DataFilters             = {};

%----------------------------------------
%---------- Propagators
%----------------------------------------

Create ForceModel NavigationFM;

NavigationFM.CentralBody                      = Earth;
NavigationFM.PrimaryBodies = {};
NavigationFM.SRP = Off;
NavigationFM.ErrorControl                     = None;

NavigationFM.PointMasses = {Earth};
NavigationFM.Drag = None;
NavigationFM.RelativisticCorrection = Off;
Create Propagator NavProp;

NavProp.FM              = NavigationFM;
NavProp.Type            = 'RungeKutta89';
NavProp.InitialStepSize = 10;
NavProp.Accuracy        = 1e-13;
NavProp.MinStep         = 0;
NavProp.MaxStep = 10;
NavProp.MaxStepAttempts = 50;

%----------------------------------------
%---------- Simulator
%----------------------------------------

Create Simulator Sim;

Sim.AddData              = {SimData};
Sim.EpochFormat          = 'UTCGregorian';
Sim.InitialEpoch         = '10 Jun 2010 00:00:00.000';
Sim.FinalEpoch = '10 Jun 2010 00:10:00.000';
Sim.MeasurementTimeStep = 60;
Sim.Propagator           = NavProp;
Sim.AddNoise = Off;

%----------------------------------------
%---------- Estimator
%----------------------------------------

Create ExtendedKalmanFilter EKF;

EKF.ShowProgress = True;
EKF.ReportFile = '@FILTER@';
EKF.Measurements         = {EstData};
EKF.Propagator           = NavProp;
EKF.ShowAllResiduals = On;
EKF.DataFilters          = {}
EKF.OutputWarmStartFile = '@WARM@';

Create Smoother FPS;

FPS.Filter               = EKF;
FPS.ShowProgress = True;
FPS.ShowAllResiduals = On;
FPS.ReportFile = '@SMOOTHER@';


%----------------------------------------
%------ Estimated value of Cd report
%----------------------------------------

Create ReportFile FilterCdReport

FilterCdReport.Filename = '@SCRATCH@';
FilterCdReport.Add         = {EstSat.UTCGregorian, EstSat.Cd}
FilterCdReport.Delimiter   = ','
FilterCdReport.WriteReport = False
FilterCdReport.FixedWidth  = Off

%----------------------------------------
%---------- Mission Sequence
%----------------------------------------

Extra.Delimiter = ',';
Create EphemerisFile Export;
Export.Spacecraft = EstSat;
Export.FileFormat = STK-TimePosVel;
Export.Filename = '@STK@';
Export.CoordinateSystem = EarthMJ2000Eq;
Export.StepSize = IntegratorSteps;
Export.IncludeEventBoundaries = true;
Export.WriteEphemeris = false;
Create ReportFile NavPhases;
NavPhases.Filename = '@PHASES@';
NavPhases.WriteHeaders = false;
BeginMissionSequence;
Toggle Export Off;
Propagate 'Probe' P(Sat) {Sat.ElapsedSecs = 10};
Propagate P(Sat) {Sat.ElapsedSecs = 10};
Report 'NavArm' NavPhases Keep;
RunSimulator Sim;
Count = 1;
Report Extra Count SimSat.A1ModJulian SimSat.X SimSat.Y SimSat.Z SimSat.VX SimSat.VY SimSat.VZ;
EstSat.OrbitErrorCovariance = diag([1e-2 1e-2 1e-2 2.5e-7 2.5e-7 2.5e-7]);
Report 'ForwardStart' NavPhases Keep;
RunEstimator EKF;

Count = 2;
Report Extra Count EstSat.A1ModJulian EstSat.X EstSat.Y EstSat.Z EstSat.VX EstSat.VY EstSat.VZ;
Report 'SmoothStart' NavPhases Keep;
Toggle Export On;
RunSmoother FPS;
Toggle Export Off;
Report 'NavDone' NavPhases Keep;
Count = 3;
Report Extra Count EstSat.A1ModJulian EstSat.X EstSat.Y EstSat.Z EstSat.VX EstSat.VY EstSat.VZ;
Report 'Witness' Values Sat.ElapsedSecs Sat.EarthMJ2000Eq.X Sat.EarthMJ2000Eq.Y Sat.EarthMJ2000Eq.Z Sat.EarthMJ2000Eq.VX Sat.EarthMJ2000Eq.VY Sat.EarthMJ2000Eq.VZ Keep Count U Cost Quantity;

